# area: typeddict
# hypothesis: Assigning to a ReadOnly[str] key of a TypedDict is rejected by mypy and ty, while a NotRequired[int] key read with get() is inferred as int, and CPython runs the write without error because ReadOnly is not enforced at runtime.
from typing import NotRequired, ReadOnly, TypedDict, assert_type, reveal_type


class Movie(TypedDict):
    title: ReadOnly[str]
    year: NotRequired[int]


def make() -> Movie:
    return {"title": "Alien"}


def bump(m: Movie) -> None:
    m["title"] = "Aliens"  # expect-error
    m["year"] = 1979


def read_year(m: Movie) -> int:
    return m.get("year", 0)


m1 = make()
reveal_type(m1["title"])
assert_type(read_year(m1), int)
try:
    bump(m1)
except TypeError:
    print("TypeError")
print(m1["title"], read_year(m1))
